import { useState } from "react";
import { Bar, BarChart, CartesianGrid, Line, LineChart, XAxis, YAxis } from "recharts";
import {
  CardContainer,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
  ChartContainer,
  ChartLegend,
  ChartLegendContent,
  ChartTooltip,
  ChartTooltipContent,
  NativeSelect,
  type ChartConfig,
} from "@nucleux/react";

const WEEKS = ["Aug 24", "Aug 31", "Sep 7", "Sep 14", "Sep 21", "Sep 28", "Oct 5", "Oct 12"];
const throughput = WEEKS.map((week, i) => ({ week, created: [9, 7, 11, 8, 12, 10, 9, 8][i], completed: [6, 8, 9, 10, 9, 13, 12, 10][i] }));
const workload = [
  { member: "Dana", open: 4 },
  { member: "Luis", open: 3 },
  { member: "Mei", open: 5 },
  { member: "Priya", open: 2 },
];

// Series colors are Nucleux tokens; ChartContainer exposes each as var(--color-<key>).
const throughputConfig: ChartConfig = {
  created: { label: "Created", color: "hsl(var(--nx-info))" },
  completed: { label: "Completed", color: "hsl(var(--nx-success))" },
};
const workloadConfig: ChartConfig = {
  open: { label: "Open tasks", color: "hsl(var(--nx-brand))" },
};

/** One chart per card: title says what it measures, description gives the unit/range. */
function ChartCard({ title, description, children }: { title: string; description: string; children: React.ReactNode }) {
  return (
    <CardContainer>
      <CardHeader className="flex-col items-start gap-1">
        <CardTitle aria-level={2}>{title}</CardTitle>
        <CardDescription>{description}</CardDescription>
      </CardHeader>
      <CardContent>{children}</CardContent>
    </CardContainer>
  );
}

/**
 * Analytics page: a range filter, then a responsive grid of chart cards.
 * Charts use ChartContainer (Recharts underneath) with token colors, a shared
 * tooltip and legend, and a text summary for screen readers.
 */
export default function AnalyticsChartsExample() {
  const [range, setRange] = useState("8");
  const rows = throughput.slice(-Number(range));
  const done = rows.reduce((s, r) => s + r.completed, 0);

  return (
    <div className="mx-auto flex max-w-6xl flex-col gap-6 p-4 sm:p-6 lg:p-8">
<header className="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between">
        <div className="min-w-0 space-y-1">
          <h1 className="text-2xl font-semibold tracking-tight text-foreground">Analytics</h1>
          <p className="text-sm text-muted-foreground">Throughput and workload across all projects.</p>
        </div>
        <div className="flex shrink-0 flex-wrap items-center gap-2">
          <NativeSelect aria-label="Time range" value={range} onChange={(e) => setRange(e.target.value)} containerClassName="w-40">
            <option value="4">Last 4 weeks</option>
            <option value="8">Last 8 weeks</option>
          </NativeSelect>
        </div>
      </header>

      <div className="grid gap-4 lg:grid-cols-2">
        <ChartCard title="Weekly throughput" description={`Tasks created vs completed, last ${range} weeks`}>
          <p className="sr-only">
            {done} tasks completed in the last {range} weeks; most in week of{" "}
            {rows.reduce((a, b) => (b.completed > a.completed ? b : a)).week}.
          </p>
          <ChartContainer config={throughputConfig} className="aspect-[16/9] w-full" aria-hidden>
            <LineChart data={rows} margin={{ left: 0, right: 8 }}>
              <CartesianGrid vertical={false} />
              <XAxis dataKey="week" tickLine={false} axisLine={false} />
              <YAxis allowDecimals={false} tickLine={false} axisLine={false} width={28} />
              <ChartTooltip content={<ChartTooltipContent config={throughputConfig} />} />
              <ChartLegend content={<ChartLegendContent config={throughputConfig} />} />
              <Line dataKey="created" stroke="var(--color-created)" strokeWidth={2} dot={false} />
              <Line dataKey="completed" stroke="var(--color-completed)" strokeWidth={2} dot={false} />
            </LineChart>
          </ChartContainer>
        </ChartCard>

        <ChartCard title="Team workload" description="Open tasks per member">
          <p className="sr-only">
            {workload.map((w) => `${w.member}: ${w.open}`).join(", ")} open tasks.
          </p>
          <ChartContainer config={workloadConfig} className="aspect-[16/9] w-full" aria-hidden>
            <BarChart data={workload}>
              <CartesianGrid vertical={false} />
              <XAxis dataKey="member" tickLine={false} axisLine={false} />
              <YAxis allowDecimals={false} tickLine={false} axisLine={false} width={28} />
              <ChartTooltip content={<ChartTooltipContent config={workloadConfig} />} />
              <Bar dataKey="open" fill="var(--color-open)" radius={4} />
            </BarChart>
          </ChartContainer>
        </ChartCard>
      </div>
    </div>
  );
}

import { useState, type MouseEvent, type ReactNode } from "react";
import { Bell, FolderKanban, LayoutDashboard, Settings, Users } from "lucide-react";
import {
  Avatar,
  Button,
  Input,
  Sidebar,
  SidebarContent,
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarInset,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarProvider,
  SidebarRail,
  SidebarTrigger,
  useSidebar,
} from "@nucleux/react";

export interface ShellLink {
  id: string;
  label: string;
  href: string;
  icon: ReactNode;
}

export const SHELL_LINKS: ShellLink[] = [
  { id: "dashboard", label: "Dashboard", href: "/", icon: <LayoutDashboard /> },
  { id: "projects", label: "Projects", href: "/projects", icon: <FolderKanban /> },
  { id: "team", label: "Team", href: "/team", icon: <Users /> },
  { id: "settings", label: "Settings", href: "/settings", icon: <Settings /> },
];

export interface AppShellProps {
  /** id of the active link. */
  current: string;
  /** Called with the link's href; wire it to your router (e.g. `navigate(href)`). */
  onNavigate: (href: string) => void;
  links?: ShellLink[];
  children: ReactNode;
}

/** The nav list. On phones the sidebar is a sheet, so close it after navigating. */
function ShellNav({ links, current, onNavigate }: { links: ShellLink[]; current: string; onNavigate: (href: string) => void }) {
  const { isMobile, setOpenMobile } = useSidebar();
  return (
    <SidebarGroup>
      <SidebarGroupLabel>Workspace</SidebarGroupLabel>
      <SidebarGroupContent>
        <SidebarMenu>
          {links.map((link) => (
            <SidebarMenuItem key={link.id}>
              <SidebarMenuButton asChild isActive={link.id === current} tooltip={link.label}>
                <a
                  href={link.href}
                  onClick={(e: MouseEvent<HTMLAnchorElement>) => {
                    e.preventDefault();
                    if (isMobile) setOpenMobile(false);
                    onNavigate(link.href);
                  }}
                >
                  {link.icon}
                  <span>{link.label}</span>
                </a>
              </SidebarMenuButton>
            </SidebarMenuItem>
          ))}
        </SidebarMenu>
      </SidebarGroupContent>
    </SidebarGroup>
  );
}

/**
 * Application shell: a Sidebar that collapses to icons on desktop (⌘B / Ctrl+B
 * or the trigger) and becomes a sheet below md, plus a top bar with search
 * and account inside SidebarInset. Page content renders below the bar.
 */
export function AppShell({ current, onNavigate, links = SHELL_LINKS, children }: AppShellProps) {
  return (
    <SidebarProvider>
      <Sidebar collapsible="icon">
        <SidebarHeader>
          <div className="truncate px-2 py-1 text-sm font-semibold text-foreground group-data-[collapsible=icon]:sr-only">
            Acme Projects
          </div>
        </SidebarHeader>
        <SidebarContent>
          <nav aria-label="Primary">
            <ShellNav links={links} current={current} onNavigate={onNavigate} />
          </nav>
        </SidebarContent>
        <SidebarRail />
      </Sidebar>

      <SidebarInset className="min-h-svh">
        <header className="sticky top-0 z-10 flex h-14 shrink-0 items-center gap-2 border-b border-border bg-background px-4 sm:px-6">
          <SidebarTrigger aria-label="Toggle navigation" />
          <Input
            type="search"
            aria-label="Search projects and tasks"
            placeholder="Search projects and tasks"
            className="hidden max-w-md sm:block"
          />
          <div className="ml-auto flex items-center gap-2">
            <Button variant="ghost" size="icon" aria-label="Notifications">
              <Bell className="size-5" />
            </Button>
            <Avatar role="user" name="Dana Kim" initials="DK" />
          </div>
        </header>
        <div className="min-h-0 flex-1">{children}</div>
      </SidebarInset>
    </SidebarProvider>
  );
}

export default function AppShellExample() {
  const [current, setCurrent] = useState("dashboard");
  return (
    <AppShell
      current={current}
      onNavigate={(href) => setCurrent(SHELL_LINKS.find((l) => l.href === href)?.id ?? "dashboard")}
    >
      <div className="mx-auto max-w-6xl p-4 sm:p-6 lg:p-8">
        <p className="text-sm text-muted-foreground">Page content renders here.</p>
      </div>
    </AppShell>
  );
}

import { useState, type FormEvent } from "react";
import {
  Alert,
  Button,
  CardContainer,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
  Checkbox,
  Input,
  Label,
} from "@nucleux/react";

/**
 * Sign-in screen: one centered card, labelled fields, inline field errors,
 * a form-level error Alert for failed sign-in, and the secondary paths
 * (forgot password, sign up) as links. Submission stays disabled while pending.
 */
export default function SignInExample({
  onSignIn = async () => {
    throw new Error("Email or password is incorrect.");
  },
}: {
  onSignIn?: (email: string, password: string, remember: boolean) => Promise<void>;
}) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [remember, setRemember] = useState(true);
  const [touched, setTouched] = useState(false);
  const [pending, setPending] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const emailInvalid = touched && !/^\S+@\S+\.\S+$/.test(email);
  const passwordInvalid = touched && password.length === 0;

  const submit = async (e: FormEvent) => {
    e.preventDefault();
    setTouched(true);
    if (!/^\S+@\S+\.\S+$/.test(email) || !password) return;
    setPending(true);
    setError(null);
    try {
      await onSignIn(email, password, remember);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Sign-in failed. Try again.");
    } finally {
      setPending(false);
    }
  };

  return (
    <main className="flex min-h-screen items-center justify-center bg-muted/40 px-4 py-12">
      <CardContainer className="w-full max-w-sm">
        <CardHeader className="flex-col items-start gap-1">
          <CardTitle role="heading" aria-level={1} className="text-xl">
            Sign in to Acme
          </CardTitle>
          <CardDescription>Welcome back. Enter your work email to continue.</CardDescription>
        </CardHeader>
        <CardContent>
          <form noValidate onSubmit={submit} className="space-y-4">
            {error && (
              <Alert variant="destructive" title="Couldn't sign you in" role="alert">
                {error}
              </Alert>
            )}
            <div className="space-y-1.5">
              <Label htmlFor="email" required>Email</Label>
              <Input
                id="email"
                type="email"
                autoComplete="email"
                value={email}
                invalid={emailInvalid}
                aria-describedby={emailInvalid ? "email-error" : undefined}
                onChange={(e) => setEmail(e.target.value)}
              />
              {emailInvalid && (
                <p id="email-error" className="text-xs text-destructive">Enter a valid email address.</p>
              )}
            </div>
            <div className="space-y-1.5">
              <div className="flex items-center justify-between">
                <Label htmlFor="password" required>Password</Label>
                <Button variant="link" asChild className="text-xs">
                  <a href="/forgot-password">Forgot password?</a>
                </Button>
              </div>
              <Input
                id="password"
                type="password"
                autoComplete="current-password"
                value={password}
                invalid={passwordInvalid}
                aria-describedby={passwordInvalid ? "password-error" : undefined}
                onChange={(e) => setPassword(e.target.value)}
              />
              {passwordInvalid && (
                <p id="password-error" className="text-xs text-destructive">Enter your password.</p>
              )}
            </div>
            <label className="flex items-center gap-2 text-sm text-foreground">
              <Checkbox checked={remember} onCheckedChange={setRemember} aria-label="Keep me signed in" />
              Keep me signed in
            </label>
            <Button type="submit" variant="cta" className="w-full" disabled={pending}>
              {pending ? "Signing in…" : "Sign in"}
            </Button>
          </form>
          <p className="mt-6 text-center text-sm text-muted-foreground">
            New to Acme?{" "}
            <Button variant="link" asChild>
              <a href="/sign-up">Create an account</a>
            </Button>
          </p>
        </CardContent>
      </CardContainer>
    </main>
  );
}

import { useState, type FormEvent } from "react";
import { Plus } from "lucide-react";
import {
  Button,
  DatePicker,
  Dialog,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  Input,
  Label,
  NativeSelect,
  Textarea,
  ToastProvider,
  useToast,
} from "@nucleux/react";

export interface TaskDraft {
  title: string;
  description: string;
  priority: "low" | "medium" | "high";
  due?: Date;
}

const EMPTY: TaskDraft = { title: "", description: "", priority: "medium" };

/**
 * Create/edit form in a Dialog: labelled fields, validation on submit with
 * inline messages, a footer with Cancel + one primary action, and a toast to
 * confirm the save. Pass `initial` to reuse the same dialog for editing.
 */
export function TaskFormDialog({
  open,
  onOpenChange,
  initial,
  onSave,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  initial?: TaskDraft;
  onSave: (task: TaskDraft) => void;
}) {
  const [draft, setDraft] = useState<TaskDraft>(initial ?? EMPTY);
  const [submitted, setSubmitted] = useState(false);
  const titleError = submitted && !draft.title.trim() ? "Give the task a title." : undefined;
  const set = <K extends keyof TaskDraft>(key: K, value: TaskDraft[K]) => setDraft((d) => ({ ...d, [key]: value }));

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setSubmitted(true);
    if (!draft.title.trim()) return;
    onSave(draft);
    setDraft(EMPTY);
    setSubmitted(false);
    onOpenChange(false);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange} className="max-w-lg">
      <form noValidate onSubmit={submit}>
        <DialogHeader>
          <DialogTitle>{initial ? "Edit task" : "New task"}</DialogTitle>
          <DialogDescription>Tasks are visible to everyone on the project.</DialogDescription>
        </DialogHeader>
        <div className="space-y-4 py-4">
          <div className="space-y-1.5">
            <Label htmlFor="task-title" required>Title</Label>
            <Input
              id="task-title"
              value={draft.title}
              invalid={!!titleError}
              aria-describedby={titleError ? "task-title-error" : undefined}
              onChange={(e) => set("title", e.target.value)}
            />
            {titleError && <p id="task-title-error" className="text-xs text-destructive">{titleError}</p>}
          </div>
          <div className="space-y-1.5">
            <Label htmlFor="task-description">Description</Label>
            <Textarea
              id="task-description"
              rows={3}
              value={draft.description}
              onChange={(e) => set("description", e.target.value)}
            />
          </div>
          <div className="grid gap-4 sm:grid-cols-2">
            <div className="space-y-1.5">
              <Label htmlFor="task-priority">Priority</Label>
              <NativeSelect
                id="task-priority"
                value={draft.priority}
                onChange={(e) => set("priority", e.target.value as TaskDraft["priority"])}
              >
                <option value="low">Low</option>
                <option value="medium">Medium</option>
                <option value="high">High</option>
              </NativeSelect>
            </div>
            <div className="space-y-1.5">
              <Label>Due date</Label>
              <DatePicker aria-label="Due date" className="w-full" value={draft.due} onValueChange={(d) => set("due", d)} />
            </div>
          </div>
        </div>
        <DialogFooter>
          <Button variant="secondary" onClick={() => onOpenChange(false)}>
            Cancel
          </Button>
          <Button type="submit" variant="cta">
            {initial ? "Save changes" : "Create task"}
          </Button>
        </DialogFooter>
      </form>
    </Dialog>
  );
}

function Page() {
  const [open, setOpen] = useState(false);
  const { toast } = useToast();
  return (
    <div className="p-6">
      <Button variant="cta" leftIcon={<Plus className="size-4" />} onClick={() => setOpen(true)}>
        New task
      </Button>
      <TaskFormDialog
        open={open}
        onOpenChange={setOpen}
        onSave={(t) => toast({ variant: "success", title: "Task created", description: t.title })}
      />
    </div>
  );
}

/** ToastProvider belongs once at the app root; it is here so the example runs alone. */
export default function FormDialogExample() {
  return (
    <ToastProvider>
      <Page />
    </ToastProvider>
  );
}

import { useMemo, useState } from "react";
import { Plus } from "lucide-react";
import { Badge, Button, DataTable, Input, NativeSelect, type DataTableProps } from "@nucleux/react";

export type ProjectStatus = "active" | "at-risk" | "done";

export interface Project {
  id: string;
  name: string;
  owner: string;
  status: ProjectStatus;
  due: string;
}

const STATUS_BADGE: Record<ProjectStatus, { label: string; variant: "success" | "destructive" | "secondary" }> = {
  active: { label: "Active", variant: "success" },
  "at-risk": { label: "At risk", variant: "destructive" },
  done: { label: "Done", variant: "secondary" },
};

// Typed from DataTableProps so the page needs no direct @tanstack/react-table import.
const columns: DataTableProps<Project, unknown>["columns"] = [
  { accessorKey: "name", header: "Project" },
  { accessorKey: "owner", header: "Owner" },
  {
    accessorKey: "status",
    header: "Status",
    cell: ({ row }) => {
      const s = STATUS_BADGE[row.original.status];
      return <Badge variant={s.variant}>{s.label}</Badge>;
    },
  },
  { accessorKey: "due", header: "Due" },
];

export const SAMPLE_PROJECTS: Project[] = [
  { id: "p1", name: "Website redesign", owner: "Dana Kim", status: "active", due: "2026-11-02" },
  { id: "p2", name: "Mobile onboarding", owner: "Luis Ortega", status: "at-risk", due: "2026-10-28" },
  { id: "p3", name: "Billing migration", owner: "Priya Shah", status: "active", due: "2026-12-15" },
  { id: "p4", name: "Q3 analytics report", owner: "Sam Lee", status: "done", due: "2026-09-30" },
];

/**
 * Collection page: header with the primary action, a search + filter toolbar,
 * and a sortable, paginated table. Filtering happens before the table so the
 * table's own pagination always reflects the filtered rows.
 */
export function ProjectListPage({ projects, onCreate }: { projects: Project[]; onCreate: () => void }) {
  const [query, setQuery] = useState("");
  const [status, setStatus] = useState<"all" | ProjectStatus>("all");

  const rows = useMemo(() => {
    const q = query.trim().toLowerCase();
    return projects.filter(
      (p) =>
        (status === "all" || p.status === status) &&
        (!q || p.name.toLowerCase().includes(q) || p.owner.toLowerCase().includes(q)),
    );
  }, [projects, query, status]);

  return (
    <div className="mx-auto flex max-w-6xl flex-col gap-6 p-4 sm:p-6 lg:p-8">
<header className="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between">
        <div className="min-w-0 space-y-1">
          <h1 className="text-2xl font-semibold tracking-tight text-foreground">Projects</h1>
          <p className="text-sm text-muted-foreground">Track every project, its owner, and its delivery status.</p>
        </div>
        <div className="flex shrink-0 flex-wrap items-center gap-2">
          <Button variant="cta" leftIcon={<Plus className="size-4" />} onClick={onCreate}>
            New project
          </Button>
        </div>
      </header>

      <div role="search" className="flex flex-col gap-3 sm:flex-row sm:items-center">
        <Input
          type="search"
          aria-label="Search projects"
          placeholder="Search by project or owner"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          className="sm:max-w-sm sm:flex-1"
        />
        <NativeSelect
          aria-label="Filter by status"
          value={status}
          onChange={(e) => setStatus(e.target.value as "all" | ProjectStatus)}
          containerClassName="sm:w-44"
        >
          <option value="all">All statuses</option>
          <option value="active">Active</option>
          <option value="at-risk">At risk</option>
          <option value="done">Done</option>
        </NativeSelect>
      </div>

      <div className="overflow-x-auto">
        <DataTable columns={columns} data={rows} pageSize={10} emptyMessage="No projects match these filters." />
      </div>
    </div>
  );
}

export default function ListPageExample() {
  return <ProjectListPage projects={SAMPLE_PROJECTS} onCreate={() => undefined} />;
}

import { useState, type FormEvent } from "react";
import { ArrowLeft, ArrowRight } from "lucide-react";
import {
  Alert,
  Button,
  CardContainer,
  CardContent,
  CardDivider,
  CardHeader,
  CardTitle,
  Input,
  Label,
  Progress,
  Radio,
  RadioGroup,
  NativeSelect,
} from "@nucleux/react";

const STEPS = ["Workspace", "Team size", "Review"] as const;

interface Answers {
  workspace: string;
  url: string;
  size: string;
  role: string;
}

/**
 * Multi-step form (onboarding, checkout, setup wizard): one card, a step
 * counter + Progress, one group of fields per step, Back/Next in a fixed
 * footer, validation per step before advancing, and a review step that lists
 * every answer before the final submit.
 */
export default function MultiStepFormExample({ onFinish = () => undefined }: { onFinish?: (a: Answers) => void }) {
  const [step, setStep] = useState(0);
  const [answers, setAnswers] = useState<Answers>({ workspace: "", url: "", size: "2-10", role: "manager" });
  const [tried, setTried] = useState(false);
  const set = (key: keyof Answers, value: string) => setAnswers((a) => ({ ...a, [key]: value }));

  const stepValid = step !== 0 || (answers.workspace.trim() !== "" && /^[a-z0-9-]+$/.test(answers.url));
  const last = step === STEPS.length - 1;

  const next = (e: FormEvent) => {
    e.preventDefault();
    setTried(true);
    if (!stepValid) return;
    setTried(false);
    if (last) onFinish(answers);
    else setStep((s) => s + 1);
  };

  return (
    <main className="mx-auto max-w-xl p-4 sm:p-8">
      <CardContainer>
        <form noValidate onSubmit={next}>
          <CardHeader className="flex-col items-stretch gap-3">
            <p className="text-sm text-muted-foreground" aria-live="polite">
              Step {step + 1} of {STEPS.length}: {STEPS[step]}
            </p>
            <Progress value={((step + 1) / STEPS.length) * 100} size="sm" aria-label="Setup progress" />
            <CardTitle role="heading" aria-level={1} className="text-xl">
              {["Name your workspace", "Tell us about your team", "Review and create"][step]}
            </CardTitle>
          </CardHeader>
          <CardDivider />
          <CardContent className="space-y-4">
            {tried && !stepValid && (
              <Alert variant="destructive" title="Check the highlighted fields" role="alert">
                Fix them to continue.
              </Alert>
            )}

            {step === 0 && (
              <>
                <div className="space-y-1.5">
                  <Label htmlFor="ws-name" required>Workspace name</Label>
                  <Input
                    id="ws-name"
                    value={answers.workspace}
                    invalid={tried && !answers.workspace.trim()}
                    onChange={(e) => set("workspace", e.target.value)}
                  />
                </div>
                <div className="space-y-1.5">
                  <Label htmlFor="ws-url" required>Workspace URL</Label>
                  <Input
                    id="ws-url"
                    value={answers.url}
                    invalid={tried && !/^[a-z0-9-]+$/.test(answers.url)}
                    aria-describedby="ws-url-hint"
                    onChange={(e) => set("url", e.target.value.toLowerCase())}
                  />
                  <p id="ws-url-hint" className="text-xs text-muted-foreground">
                    Lowercase letters, numbers and dashes: acme.app/{answers.url || "your-team"}
                  </p>
                </div>
              </>
            )}

            {step === 1 && (
              <>
                <div className="space-y-1.5">
                  <Label htmlFor="team-size">Team size</Label>
                  <NativeSelect id="team-size" value={answers.size} onChange={(e) => set("size", e.target.value)}>
                    <option value="1">Just me</option>
                    <option value="2-10">2–10</option>
                    <option value="11-50">11–50</option>
                    <option value="51+">51 or more</option>
                  </NativeSelect>
                </div>
                <div className="space-y-2">
                  <p className="text-sm font-medium text-foreground">Your role</p>
                  <RadioGroup label="Your role" value={answers.role} onValueChange={(v) => set("role", v)}>
                    {[["manager", "Project manager"], ["engineer", "Engineer"], ["designer", "Designer"]].map(([v, l]) => (
                      <label key={v} className="flex items-center gap-2 text-sm text-foreground">
                        <Radio value={v} /> {l}
                      </label>
                    ))}
                  </RadioGroup>
                </div>
              </>
            )}

            {step === 2 && (
              <dl className="divide-y divide-border text-sm">
                {[
                  ["Workspace", answers.workspace],
                  ["URL", `acme.app/${answers.url}`],
                  ["Team size", answers.size],
                  ["Role", answers.role],
                ].map(([k, v]) => (
                  <div key={k} className="flex justify-between gap-4 py-2">
                    <dt className="text-muted-foreground">{k}</dt>
                    <dd className="font-medium text-foreground">{v}</dd>
                  </div>
                ))}
              </dl>
            )}

            <div className="flex items-center justify-between gap-3 pt-2">
              <Button
                variant="ghost"
                leftIcon={<ArrowLeft className="size-4" />}
                disabled={step === 0}
                onClick={() => setStep((s) => s - 1)}
              >
                Back
              </Button>
              <Button type="submit" variant="cta" rightIcon={last ? undefined : <ArrowRight className="size-4" />}>
                {last ? "Create workspace" : "Next"}
              </Button>
            </div>
          </CardContent>
        </form>
      </CardContainer>
    </main>
  );
}

import type { ReactNode } from "react";
import { AlertTriangle, FolderOpen, RefreshCw } from "lucide-react";
import { Button, Empty, EmptyContent, EmptyDescription, EmptyHeader, EmptyMedia, EmptyTitle, Skeleton } from "@nucleux/react";

export type LoadState<T> =
  | { status: "loading" }
  | { status: "error"; message: string }
  | { status: "ready"; data: T };

/** Placeholder that mirrors the shape of a list while it loads. */
export function ListSkeleton({ rows = 5 }: { rows?: number }) {
  return (
    <div role="status" aria-live="polite" className="space-y-3">
      <span className="sr-only">Loading…</span>
      {Array.from({ length: rows }, (_, i) => (
        <div key={i} className="flex items-center gap-3">
          <Skeleton circle className="size-8" />
          <div className="flex-1 space-y-2">
            <Skeleton className="h-4 w-1/3" />
            <Skeleton className="h-3 w-2/3" />
          </div>
        </div>
      ))}
    </div>
  );
}

/**
 * Renders the right state for async data: a skeleton while loading, a
 * recoverable error with Retry, an empty state with a primary action, or the
 * content itself.
 */
export function AsyncContent<T>({
  state,
  isEmpty,
  onRetry,
  empty,
  children,
}: {
  state: LoadState<T>;
  isEmpty: (data: T) => boolean;
  onRetry: () => void;
  empty: { title: string; description: string; action?: ReactNode };
  children: (data: T) => ReactNode;
}) {
  if (state.status === "loading") return <ListSkeleton />;
  if (state.status === "error") {
    return (
      <Empty role="alert" className="border border-border">
        <EmptyHeader>
          <EmptyMedia variant="icon" className="bg-destructive/10 text-destructive">
            <AlertTriangle />
          </EmptyMedia>
          <EmptyTitle>Couldn&apos;t load this page</EmptyTitle>
          <EmptyDescription>{state.message}</EmptyDescription>
        </EmptyHeader>
        <EmptyContent>
          <Button variant="secondary" leftIcon={<RefreshCw className="size-4" />} onClick={onRetry}>
            Retry
          </Button>
        </EmptyContent>
      </Empty>
    );
  }
  if (isEmpty(state.data)) {
    return (
      <Empty className="border border-border">
        <EmptyHeader>
          <EmptyMedia variant="icon">
            <FolderOpen />
          </EmptyMedia>
          <EmptyTitle>{empty.title}</EmptyTitle>
          <EmptyDescription>{empty.description}</EmptyDescription>
        </EmptyHeader>
        {empty.action && <EmptyContent>{empty.action}</EmptyContent>}
      </Empty>
    );
  }
  return <>{children(state.data)}</>;
}

export default function PageStatesExample() {
  const retry = () => undefined;
  return (
    <div className="mx-auto grid max-w-5xl gap-6 p-6 md:grid-cols-3">
      <AsyncContent state={{ status: "loading" }} isEmpty={() => false} onRetry={retry} empty={{ title: "", description: "" }}>
        {() => null}
      </AsyncContent>
      <AsyncContent
        state={{ status: "error", message: "The server didn't respond. Your filters are kept." }}
        isEmpty={() => false}
        onRetry={retry}
        empty={{ title: "", description: "" }}
      >
        {() => null}
      </AsyncContent>
      <AsyncContent
        state={{ status: "ready", data: [] as string[] }}
        isEmpty={(d) => d.length === 0}
        onRetry={retry}
        empty={{
          title: "No projects yet",
          description: "Create a project to start tracking tasks.",
          action: <Button variant="cta">New project</Button>,
        }}
      >
        {(items) => <ul>{items.map((i) => <li key={i}>{i}</li>)}</ul>}
      </AsyncContent>
    </div>
  );
}

